    ///
    /// - Parameters:
    ///   - team: Team ID (`team_...`). The team to remove the member from.
    ///   - user: User ID (`usr_...`) of the existing member whose role should be changed.
    ///   - input: Request body.
    /// - Returns: The updated team membership reflecting the new role.
    public func update(team: String, user: String, input: MemberUpdateInput) async throws -> TeamMembership {
        return try await http.request("/api/v1/teams/\(team)/members/\(user)", method: "PATCH", body: input)
    }
}

